import { ScreenManager } from '../../../engine/ScreenManager.js';
import '../../../lib/pixi.js';
import { Invoker } from '../../../core/commandPattern/Invoker.js';
import { Container, Graphics, TextStyle } from '../../../core/fff.js';
import { BT } from '../../../engine/BT.js';
import { BaseScreen } from '../../../engine/BaseScreen.js';
import { Config } from '../../../engine/Config.js';
import { Datas } from '../../../engine/Datas.js';
import { DatasManager } from '../DatasManager.js';
import { Game } from './Game.js';
import { AttaqueReceiver } from '../entities/AttaqueReceiver.js';
import { BubblePoint } from '../entities/BubblePoint.js';
import { CommandAttack } from '../entities/CommandAttack.js';
import { FlaskGauge } from '../entities/FlaskGauge.js';
import { Monstre } from '../entities/Monstre.js';
import { MonstreStats } from '../entities/MonstreStats.js';

// [**]
// Systeme de TL basée sur le DPS
// transition IN/OUT vers Game
// Navigate vers GameOver ou Game

// shake screen + flash sur crit
// shake monstre + flash sur coup normal
// bubble dommage
// cooldown sur popo / spells

export class FightScreen extends BaseScreen {
    constructor() {
        super();
    }

    start() {
        this._nextScreen = Game;
        super.start();

        this.visible = true;

        BT.stage.addChildAt(Datas.atlas[Datas.BACKGROUND_IMAGE_COMPASS], 0);
        Datas.atlas[Datas.BACKGROUND_IMAGE_COMPASS].x = 768;

        // the main game container
        let container = this.stage.addChild(new Container());

        this.invoker = new Invoker();

        this.playerStats = DatasManager.playerStats;
        this.stalfosStats = new MonstreStats(MonstreStats.TYPE_SQUELETTE, 15, 125, (43 + Math.floor(Math.random() * 87)), 1, 4, MonstreStats.ATT_PHYSIQUE, .12);


        ///////////////////////////////////////////
        // FIGHT        
        let battleScreen = new Graphics();
        battleScreen.clear();
        battleScreen.lineStyle(3, Config.color.BEIGE);
        battleScreen.beginFill(Config.color.DARKGRAY);
        battleScreen.drawRect(0, 0, 768, 768);
        battleScreen.endFill();
        container.addChild(battleScreen);

        let encounterData = this.encounterData = DatasManager.encounters.shift();

        this.encounter = new Monstre(Datas.atlas[encounterData.name], 0, 0, 100);
        this.encounter.px = .5; // x = px * 768 (comme dans onEnterFrame) : bien place des le premier affichage
        this.encounter.y = Config.STAGEHEIGHT - 128; // from -10 vers -128 avec un zoom/scale arrière
        container.addChild(this.encounter);

        ///////////////////////////////////////////
        // UI        
        let lifeGauge = this.lifeGauge = new FlaskGauge(48, 0xAA0000, 0xBB0000);
        lifeGauge.updateTextValues(DatasManager.playerStats.hp, DatasManager.playerStats.maxHp);
        lifeGauge.position.set(55, Config.STAGEHEIGHT - 55);
        container.addChild(lifeGauge);

        let manaGauge = this.manaGauge = new FlaskGauge(48, 0x000099, 0x0000FF);
        manaGauge.updateTextValues(DatasManager.playerStats.mp, DatasManager.playerStats.maxMp);
        manaGauge.position.set(768 - 55, Config.STAGEHEIGHT - 55);
        container.addChild(manaGauge);

        let fontStyleTitle = new TextStyle({
            fontFamily: Config.VECTOR_FUTURE_FONT,
            fill: Config.style.ACCENT,
            fontSize: 20
        });

        this.bubble = new BubblePoint(fontStyleTitle);
        container.addChild(this.bubble);

        ///////////////////////////////////////////
        // Tick
        this.time = 0;
        this.frame = 0;
        BT.ticker.start();
    }

    onEnterFrame(pDt) {
        // le combat ne demarre qu'une fois l'ecran de chargement leve (sinon il se jouerait derriere le voile)
        if (ScreenManager.loading) return;
        this.time += pDt;
        
        this.frame += 1;

        if (this.frame % 30 == 0) {
            if (this.stalfosStats.hp > 0) {
                let playerAtt = new CommandAttack(new AttaqueReceiver(this.stalfosStats), this.playerStats.attMin, this.playerStats.attMax);
                let bb = this.encounter.worldTransform;
                this.bubble.show(
                    playerAtt.execute(),
                    (bb.tx - this.encounter.width / 2) + Math.random() * this.encounter.width,
                    (bb.ty - this.encounter.height) + Math.random() * this.encounter.height
                );
                this.invoker.storeCommand(playerAtt);
                this.invoker.execute();
            } else {
                this.encounter.visible = false;
                this.transitionOut();
            }
        }

        if (this.frame % 45 == 0) {
            if (this.stalfosStats.hp > 0) {
                let stalfosAtt = new CommandAttack(new AttaqueReceiver(this.playerStats), this.stalfosStats.attMin, this.stalfosStats.attMax);
                this.invoker.storeCommand(stalfosAtt);
                this.invoker.execute();
            }
        }

        this.encounter.px = .5 + Math.sin(this.time) / 200;

        // update GUI
        this.lifeGauge.value = this.playerStats.hp / this.playerStats.maxHp;
        this.lifeGauge.updateTextValues(DatasManager.playerStats.hp, DatasManager.playerStats.maxHp);
        this.lifeGauge.update(pDt);

        this.manaGauge.value = DatasManager.playerStats.mp / DatasManager.playerStats.maxMp;
        this.manaGauge.updateTextValues(DatasManager.playerStats.mp, DatasManager.playerStats.maxMp);
        this.manaGauge.update(pDt);
    }

    /** retour a l'exploration du donjon (Game restaure la position et le cap du joueur) */
    transitionOut() {
        // flash, puis ecran de chargement le temps que le donjon se reconstruise
        return super.transitionOut({ effect: 'flash', color: 0xFFFFFF, delay: 1, freeze: true, loading: { message: "Retour au donjon..." } });
    }


}