import { Container, Graphics, Text } from '../../../core/fff.js';
import { Config } from '../../../engine/Config.js';

export class FlaskGauge extends Container {
    constructor(pSize, pColor1, pColor2) {
        super();   

        let gfx = this.gfx = new Graphics();

        this.size = pSize;
        this.size2 = pSize<<1;

        this.color1 = pColor1;
        this.color2 = pColor2;

        let myMask = new Graphics();
        myMask.lineStyle(0);
        myMask.beginFill(0x0);
        myMask.drawCircle(0,0, this.size);
        myMask.endFill();        
        this.addChild(myMask);
        gfx.mask = myMask;
        this.addChild(gfx);

        this.hp = 1;
        gfx.rotation = Math.PI;

        this.frame = 0;
        this.freq = .01; // agitation entre .00 (arret) et .09 (agité)
        this.slices = 6; // 2..20

        let tf = this.tf = new Text("",{ fontFamily: Config.VECTOR_FUTURE_FONT, fontSize: 16, fill: Config.style.PRIMARY_LIGHT, align: 'center', dropShadowAngle: Math.PI / 2 });
        tf.anchor.set(.5,.5);
        this.addChild(tf);
    }

    update(dt){
        this.frame++;
    }

    calcWaveHeight(pX){
        return 1+Math.cos((6.28 * this.freq * this.frame)+pX);
    }

    updateTextValues(pValue1, pValue2){
        if(this.tf){
            this.tf.text = pValue1 + "/" + pValue2;
        }
    }

    /**
     * @param {number} pValue, 0..1
     */
    set value(pValue){        
        this.gfx.clear();
        this.gfx.lineStyle(2, this.color2);
        this.gfx.beginFill(this.color1);
        // bas
        this.gfx.moveTo(-this.size-2, -this.size-2);
        this.gfx.lineTo(this.size+2, -this.size-2);        
        // surface
        let lastX = this.size+2;
        let inc = 100 / (this.slices - 1); // 100 == (this.size+2 + Math.abs(-this.size-2)) , aka 48 * 2 +4        
        for(let i = 0 ; i < this.slices ; i++){
            this.gfx.lineTo(lastX, (-this.size-4 + this.size2 * pValue) + this.calcWaveHeight(lastX));
            lastX -= inc;
        }
        this.gfx.endFill();        
    }
}