export class PlayerStats {
    constructor(pName, pClass) {
        this.name = pName;
        this.class = pClass;

        // classe barbare
        // +3 force
        // +1 dext
        // +1 int
        // +2 vit (+1 par niveau au dessus 35)

        this._level = 0;
        this._xp = 0;

        // vie
        // Vitality: Initially increases life by 10 hit points. After a character reaches level 36
        // the life gains from Vitality begin to go up by only 1 per point
        // up to level 60, where each point is +35 life        
        this.VIT = 7;
        this.dmg = 0;

        // combat basé sur la force
        // Increases Warrior's damage by 1% per point, and armor for all classes by 1 per point.
        this.STR = 7;

        // combat basé sur la dext
        // Increases Rogue damage by 1% per point, and armor for all classes by 1 per point
        this.DEX = 7;

        // combat basé sur l'intel
        // Increases all Wizard damage by 1% per point, and all resistances at the rate of 10 Intelligence per 'whole' point of resist.
        this.INT = 7;
        this.mpDmg = 70;
        // init stats
        this.addXP(0);

        // degats en fonction de l'équipement (ici épée courte)
        this.attMin = 2;
        this.attMax = 5;
        this.aps = 1.4;
    }

    addXP(pValue) {
        if (pValue) {
            this._xp += pValue;
            this.calcLevel();
        }
    }

    calcLevel() {
        let xpTable = [0, 1000, 2600, 4500, 6600, 9000, 11700, 14000, 16500, 19200, 22100, 25200, 28500, 32000, 35700, 39600, 43700, 48000, 52500, 57200, 62100, 67200, 72500, 78000, 83700, 89600, 95700, 102000, 108500, 115200];

        let i = 0;
        while (i < xpTable.length) {
            if (this._xp < xpTable[i]) {
                break;
            }
            i++;
        }

        this._level = i;

        // recal des stats en fonction du niveau calculé
        this.STR = 7 + (3 * this._level);
        this.DEX = 7 + (1 * this._level);
        this.INT = 7 + (1 * this._level);
        if (this._level < 36) {
            this.VIT = 7 + (this._level * 2);
        } else {
            this.VIT = 77 + (this._level - 35);
        }
    }

    get level() {
        return this._level;
    }

    get maxHp() {
        if (this._level < 36) {
            return 40 + (this.VIT * 10);
        } else {
            return 40 + (77 * 10) + ((this.VIT - 77) * 35);
        }
    }

    get hp() {
        return Math.max(0, this.maxHp - this.dmg);
    }

    get mp(){
        return Math.max(0, this.maxMp - this.mpDmg);
    }

    get maxMp(){
        return 100;
    }
}