export class Game extends BaseScreen {
    constructor() {
        super();
    }

    start() {
        this._nextScreen = Game;
        super.start();
        this.visible = true;
        this.raycaster = null;

        BT.stage.addChildAt(Datas.atlas[Datas.BACKGROUND_IMAGE_COMPASS], 0);
        Datas.atlas[Datas.BACKGROUND_IMAGE_COMPASS].x = 768;

        // the main game container
        let container = this.stage.addChild(new Container());

        // player
        // retour de combat : l'ennemi affronte disparait du labyrinthe
        DatasManager.removeEngagedEnemies();

        let playerPosition = (DatasManager.lastPlayerPosition) ? DatasManager.lastPlayerPosition : new Point((5 * 64) + 32, (8 * 64) + 32);
        // cap = cran d'angle entier (60 = Nord). L'ancien hack "-0.001" (angle pile sur un quart = affichage faux) est inutile :
        // les tables cos/sin sont exactes et la visibilite ne depend plus de l'arrondi.
        let playerDirection = (DatasManager.lastPlayerDirection != null) ? DatasManager.lastPlayerDirection : 60;

        this.player = new PlayerTopDown(
            this.gameInput1,
            Datas.atlas[Datas.BALL_GREEN],
            playerPosition.x, playerPosition.y,
            playerDirection);

        this._fixed = new FixedStep(1 / 60);

        ///////////////////////////////////////////
        // UI

        let azertyBtn = this.azertyBtn = new ButtonScale3("Move : QSDZ / AE", 768 + 128, 280);
        this.stage.addChild(azertyBtn);
        azertyBtn.on(BaseButton.POINTER_DOWN, (pEvent) => {
            Config.UP = "KeyW"; // z
            Config.DOWN = "KeyS"; // s
            Config.LEFT = "KeyA"; // q
            Config.RIGHT = "KeyD"; // d
            Config.ACTION2 = "KeyE"; // e
            Config.ACTION3 = "KeyQ"; // a
            this.player.clearInputs();
            let gi = this.player.gameInput;
            gi.changeKeyLayout(Config.UP, Config.DOWN, Config.LEFT, Config.RIGHT, Config.ACTION1, Config.ACTION2, Config.ACTION3);
            this.showMessageBox(MsgBox.MB_OK + MsgBox.MB_ICON_INFORMATION, "Movement AZERTY", "Z:UP\nQ:LEFT\nS:DOWN\nD:LEFT\nA:ROTATE LEFT\nE:ROTATE RIGHT");
        });

        let spaceBtn = new ButtonScale3("SPACEBAR = mini-map", 768 + 128, 256 + 128 - 64);
        this.stage.addChild(spaceBtn);
        spaceBtn.on(BaseButton.POINTER_DOWN, (pEvent) => {
            this.player.action1OnRelease();
        });

        // Raycaster window test implem        
        this.raycaster = new Raycaster(this.player, 0, 0, 768, 768);
        container.addChild(this.raycaster);
        // zone de rendu : ?view=8 (profondeur en cases, defaut 4, 14 = tout le labyrinthe) et ?side=2 (largeur laterale max)
        const params = new URLSearchParams(location.search);
        const view = parseFloat(params.get('view'));
        const side = parseFloat(params.get('side'));
        if (view > 0) this.raycaster.setViewDistance(view, side > 0 ? side : Infinity);
        // brouillard : ?fog=2 (distance de depart en cases, defaut 1), ?fog=off pour le couper
        const fog = params.get('fog');
        if (fog === 'off') this.raycaster.setFog(Infinity);
        else if (parseFloat(fog) >= 0) this.raycaster.setFog(parseFloat(fog));

        // appareil tactile : croix de deplacement a gauche, rotations a droite
        if (TouchControls.isTouchDevice()) {
            const H = Config.STAGEHEIGHT;
            container.addChild(TouchControls.create(this.gameInput1, {
                dpad: { x: 190, y: H - 190, gap: 84, radius: 42 },
                buttons: [
                    { key: 'action3', x: 480, y: H - 130, radius: 56, icon: Datas.atlas[Datas.BUTTON_RR] },
                    { key: 'action2', x: 690, y: H - 130, radius: 56, icon: Datas.atlas[Datas.BUTTON_RL] }
                ]
            }));
        }

        let gamepadHelp = new Sprite(Datas.atlas[Datas.GAMEPAD_HELP]);
        gamepadHelp.x = 896;
        gamepadHelp.y = 430;
        gamepadHelp.scale.set(.66, .66);
        gamepadHelp.anchor.set(.5, .5);
        container.addChild(gamepadHelp);

        let lifeGauge = this.lifeGauge = new FlaskGauge(48, 0xAA0000, 0xBB0000);
        lifeGauge.updateTextValues(DatasManager.playerStats.hp, DatasManager.playerStats.maxHp);
        lifeGauge.position.set(55, Config.STAGEHEIGHT - 55);
        container.addChild(lifeGauge);

        let manaGauge = this.manaGauge = new FlaskGauge(48, 0x000099, 0x0000FF);
        manaGauge.updateTextValues(DatasManager.playerStats.mp, DatasManager.playerStats.maxMp);
        manaGauge.position.set(768 - 55, Config.STAGEHEIGHT - 55);
        container.addChild(manaGauge);


        ///////////////////////////////////////////
        // ETATS DU JEU
        //   EXPLORE : le joueur se deplace, les ennemis patrouillent
        //   CONTACT : un combat est declenche (contact avec un ennemi, ou touche P) : le joueur finit son geste
        //             (marche jusqu'au centre de la case, quart de tour) sans commandes
        //   FIGHT   : on part vers FightScreen (la position et le cap sont memorises a cet instant)
        this._fightEnemy = null;
        this.fsm = new StateMachine(this, {
            EXPLORE: {
                update: (g, dt) => {
                    g.gameInput1.update(dt);
                    g.stepPlayer(dt);
                    g.updateEnemies(dt);
                    const enemy = g.findContact();
                    if (enemy) g.beginContact(enemy);
                }
            },
            CONTACT: {
                enter: (g) => g.player.clearInputs(),
                update: (g, dt) => g.stepPlayer(dt),
                // le combat demarre quand le joueur est pile au centre d'une case, face a un point cardinal :
                // c'est la position qui sera restauree au retour du combat
                transitions: [{ to: 'FIGHT', when: (g) => g.isPlayerAligned() }]
            },
            FIGHT: {
                enter: (g) => g.startFight()
            }
        }, 'EXPLORE');

        // Touche P : declenche un combat de test (touche du moteur : Key gere clavier, perte de focus et
        // nettoyage ; press = front montant)
        this._keyFight = new Key('KeyP');
        this._keyFight.press = () => {
            if (this.fsm.is('EXPLORE')) {
                this._fightEnemy = null;
                this.fsm.change('CONTACT');
            }
        };

        ///////////////////////////////////////////
        // Tick
        BT.ticker.start();
    }

    /**
     * Debut d'une rencontre : on memorise ou etait le joueur (position + cap), puis flash rouge et
     * passage a FightScreen. Au retour du combat, Game se reconstruit a cette position.
     * pDatas : { monstre, posX, posY }
     */
    enterFight(pDatas) {
        DatasManager.lastPlayerPosition = new Point(pDatas.posX, pDatas.posY);
        DatasManager.lastPlayerDirection = this.player.angleIndex;
        DatasManager.encounterStats = [pDatas.monstre];
        // flash rouge, puis ecran de chargement (comme au retour du combat)
        this.transitionTo(FightScreen, { effect: 'flash', color: 0xAA0000, delay: 1, freeze: true, loading: { message: "Combat !" } });
    }

    /** Le joueur est-il a l'arret, au centre d'une case, face a un point cardinal ? */
    isPlayerAligned() {
        const p = this.player;
        return ((p.x + 32) % 64 == 0) && ((p.y + 32) % 64 == 0) && (p.angleIndex % 20 == 0);
    }

    /** Un pas de simulation du joueur par 1/60 s (avant : 2 px par IMAGE, donc 2x plus vite sur un ecran 120 Hz) */
    stepPlayer(pDt) {
        this._fixed.run(pDt, () => this.player.update());
    }

    updateEnemies(pDt) {
        const ctx = { raycaster: this.raycaster, rng: DatasManager.rng };
        const near = this.raycaster.viewDistance + 1.5; // en cases
        for (const e of DatasManager.enemies) {
            e.update(pDt, ctx);
            // le Raycaster ne redessine que si la vue change : un ennemi qui bouge pres du joueur la change
            if (e.moved && Math.hypot(e.x - this.player.x, e.y - this.player.y) < near * 64) this.raycaster.invalidate();
        }
    }

    /** ennemi assez proche du joueur pour declencher le combat (ou null) */
    findContact() {
        for (const e of DatasManager.enemies) {
            if (!e.engaged && Math.hypot(e.x - this.player.x, e.y - this.player.y) < Game.CONTACT_DISTANCE) return e;
        }
        return null;
    }

    beginContact(pEnemy) {
        this._fightEnemy = pEnemy;
        pEnemy.engage();
        this.fsm.change('CONTACT');
    }

    /** Prepare la rencontre (celle de l'ennemi touche, ou un combat de test avec la touche P) et lance le combat. */
    startFight() {
        const e = this._fightEnemy;
        DatasManager.encounters.push({
            type: DatasManager.ENCOUNTER_FIGHT,
            name: e ? e.name : Datas.STALFOS,
            gridX: e ? e.gridX : (this.player.x / 64) | 0,
            gridY: e ? e.gridY : (this.player.y / 64) | 0,
            bonusXp: 10
        });
        this.enterFight({ monstre: "Stalfos", posX: this.player.x, posY: this.player.y });
    }

    playerAction(pAction) {
        if (pAction === GameInput.ACTION1 && this.fsm.is('EXPLORE')) {
            // DatasManager.playerStats.dmg += 25; // test des degats            
            this.raycaster.hitSpace();
        }
    }

    destroy() {
        if (this._keyFight) this._keyFight.destroy();
        super.destroy();
    }

    onEnterFrame(pDt) {
        // une boite de message (menu modal) met la logique du jeu en attente : les ennemis ne bougent plus
        if (!(this._menu && this._menu.active)) this.fsm.update(pDt);
        // update ray caster
        this.raycaster.update(pDt);
        // update GUI
        this.lifeGauge.value = DatasManager.playerStats.hp / DatasManager.playerStats.maxHp;
        this.lifeGauge.updateTextValues(DatasManager.playerStats.hp, DatasManager.playerStats.maxHp);
        this.lifeGauge.update(pDt);

        this.manaGauge.value = DatasManager.playerStats.mp / DatasManager.playerStats.maxMp;
        this.manaGauge.updateTextValues(DatasManager.playerStats.mp,DatasManager.playerStats.maxMp);
        this.manaGauge.update(pDt);
    };
}

Game.CONTACT_DISTANCE = 28; // px : distance joueur-ennemi qui declenche le combat