import { Graphics, Sprite } from '../../../core/fff.js';
import { BT } from '../../../engine/BT.js';
import { Config } from '../../../engine/Config.js';
import { Datas } from '../../../engine/Datas.js';
import { DatasManager } from '../DatasManager.js';
import { COS, SIN } from './PlayerTopDown.js';

export class Raycaster extends Graphics {
    constructor(pPlayer, pX, pY, pWidth = 0, pHeight = 0, pColor = 0x0) {
        super();

        this.oriX = pX;
        this.oriY = pY;

        this.x = pX;
        this.y = pY;

        this.eventMode = 'none';

        this.WIDTH = pWidth;
        this.HEIGHT = pHeight;

        this.player = pPlayer;
        this.playerGridX = 0;
        this.playerGridY = 0;
        this.playerRoomIndex = 0;
        this.lastPlayerX = -1;
        this.lastPlayerY = -1;
        this.lastPlayerAngle = 999;
        this._dirty = true; // force le premier dessin

        let mask = new Graphics();
        mask.beginFill(Config.color.DARKBLUE);
        mask.drawRect(this.x, this.y, pWidth, pHeight);
        mask.endFill();
        this.mask = mask;

        // MAZE

        this.playerStartGridX = 0;
        this.playerStartGridY = 0;

        this._spaceKeyCounter = 0;

        this.mazeGridX = 14;
        this.mazeGridY = 14;
        this.maze = [
            0x0, 0x0, 0x0, 0x0, 0x8, 0x9, 0x9, 0xB, 0x9, 0x7, 0x0, 0x0, 0x0, 0x0,
            0x0, 0x0, 0x0, 0x0, 0xA, 0x0, 0x0, 0xA, 0x0, 0xA, 0x0, 0x0, 0x0, 0x0,
            0x8, 0x7, 0x0, 0x0, 0xA, 0x0, 0x0, 0xA, 0x0, 0xA, 0x0, 0x0, 0x0, 0x0,
            0x6, 0xD, 0x7, 0x0, 0xE, 0x9, 0x9, 0xF, 0x9, 0x5, 0x0, 0x0, 0x0, 0x0,
            0x0, 0x0, 0xA, 0x0, 0xA, 0x0, 0x0, 0xA, 0x0, 0x0, 0x3, 0x0, 0x0, 0x0,
            0x0, 0x0, 0xA, 0x0, 0x6, 0x9, 0x9, 0xF, 0x9, 0x9, 0xC, 0x0, 0x0, 0x0,
            0x0, 0x0, 0xA, 0x0, 0x0, 0x0, 0x0, 0xA, 0x0, 0x0, 0xA, 0x0, 0x0, 0x0,
            0x0, 0x0, 0x6, 0xB, 0x9, 0x7, 0x0, 0xA, 0x0, 0x0, 0xA, 0x0, 0x0, 0x0,
            0x0, 0x3, 0x0, 0xA, 0x0, 0xA, 0x0, 0x6, 0x9, 0x9, 0xF, 0x4, 0x0, 0x0,
            0x0, 0xA, 0x0, 0xA, 0x0, 0xA, 0x0, 0x0, 0x0, 0x0, 0xA, 0x0, 0x0, 0x0,
            0x2, 0xD, 0xB, 0xD, 0x9, 0xF, 0x9, 0x7, 0x0, 0x0, 0xA, 0x0, 0x0, 0x0,
            0x0, 0x0, 0xA, 0x0, 0x0, 0xA, 0x0, 0x6, 0x9, 0xB, 0xD, 0x7, 0x0, 0x0,
            0x0, 0x0, 0x1, 0x0, 0x0, 0x1, 0x0, 0x0, 0x0, 0xA, 0x0, 0xA, 0x0, 0x0,
            0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x6, 0x9, 0x5, 0x0, 0x0
        ];
        this._buildEdges();
        this._wallCount = 0;
        this._cellCount = 0;
        this.lastLineCount = 0;
        this.setViewDistance(Raycaster.DEFAULT_VIEW_DISTANCE);
        this._vStamp = new Uint32Array((this.mazeGridX + 1) * (this.mazeGridY + 1));
        this._frame = 0;
        this._ta = 0;
        this._tb = 1;
        this._ix = 0;
        this._iz = 0;
        this.updatePlayerGridPosition();

        // ennemis : un sprite par ennemi de DatasManager.enemies, projete a chaque redessin (voir _updateEnemies)
        this.sortableChildren = true; // les plus lointains dessines en premier (zIndex = -profondeur)
        this._enemySprites = DatasManager.enemies.map((e) => {
            const spr = new Sprite(Datas.atlas[e.name]);
            spr.anchor.set(0.5, 1); // ancre = les pieds : poses sur le sol
            spr.visible = false;
            this.addChild(spr);
            return spr;
        });

        this.time = 0;
    }

    /**
     * Zone de rendu.
     *  pDepth : profondeur, en CASES, dans l'axe de vue (2.5 = valeur d'origine ; 14 = tout le labyrinthe).
     *  pSide  : largeur laterale maximale en cases (Infinity = pas de limite, seul le champ de vision compte).
     * La zone n'est plus un disque autour du joueur mais un "cone" aligne sur la vue (FOV 90 degres) :
     * une case n'est examinee que si une partie d'elle peut etre a l'ecran. Meme portee dans les couloirs,
     * beaucoup moins de cases (et de tests de visibilite) a examiner.
     * Les tampons sont dimensionnes ici, une seule fois : aucune allocation pendant le jeu.
     */
    setViewDistance(pDepth, pSide = Infinity) {
        this.viewDistance = Math.max(1, pDepth);
        this.viewSide = pSide;
        const R = Math.ceil(this.viewDistance) + 2;
        const maxCells = Math.min((2 * R + 1) ** 2, this.mazeGridX * this.mazeGridY);
        this._walls = new Float64Array(4 * 4 * maxCells);            // 4 murs x 4 nombres par case
        // traits par bande de brouillard (une couleur par bande) : au plus 10 traits (4 nombres) par mur
        this._bandLines = [];
        for (let b = 0; b < Raycaster.FOG_BANDS; b++) this._bandLines.push(new Float64Array(this._walls.length * 10));
        this._bandN = new Int32Array(Raycaster.FOG_BANDS);
        this._applyFog();
        this._queue = new Int16Array(this.mazeGridX * this.mazeGridY * 4);                 // file du parcours (une case peut etre remise en file si son secteur s'elargit)
        this._cellStamp = new Uint32Array(this.mazeGridX * this.mazeGridY);
        this._cellQueued = new Uint32Array(this.mazeGridX * this.mazeGridY);
        this._win = new Float64Array(this.mazeGridX * this.mazeGridY * 4);
        this._full = new Uint8Array(this.mazeGridX * this.mazeGridY);
        this._cellFrame = 0;
        this._cells = new Int16Array(2 * maxCells);                  // cases de la zone de rendu (pour la mini-map de debug)
        this._dirty = true;
    }

    calcPlayerGridPosition(pOffsetX = 0, pOffsetY = 0) {
        let gridX = pOffsetX + (this.playerGridX = (this.player.x / Raycaster.WALL_SIZE) | 0);
        let gridY = pOffsetY + (this.playerGridY = (this.player.y / Raycaster.WALL_SIZE) | 0);
        return { x: gridX, y: gridY };
    }

    updatePlayerGridPosition() {
        let gp = this.calcPlayerGridPosition();
        this.playerRoomIndex = BT.clamp((gp.y * this.mazeGridX) + gp.x, 0, this.mazeGridX * this.mazeGridY - 1);
        // passages ouverts de la cellule du joueur (le joueur ne peut avancer que vers un passage ouvert)
        const open = Raycaster.OPEN[this.maze[this.playerRoomIndex]];
        const w = this.player.walls;
        w[0] = (open & Raycaster.N) != 0;
        w[1] = (open & Raycaster.E) != 0;
        w[2] = (open & Raycaster.S) != 0;
        w[3] = (open & Raycaster.W) != 0;
    }

    /**
     * Construit la liste des murs a considerer, dans le repere du labyrinthe (x1, y1, x2, y2 par mur,
     * Float64Array, aucune allocation). Chaque mur est oriente dans le sens des aiguilles d'une montre
     * autour de SA cellule : c'est ce qui permet de ne garder que les murs vus "de l'interieur"
     * (x1 <= x2 a l'ecran).
     *
     * PARCOURS PAR "PORTAILS" : on part de la case du joueur. Chaque passage ouvert vers une case voisine
     * est un portail : vu de la camera, il ne laisse passer qu'un SECTEUR d'angles (entre les directions
     * de ses deux extremites). On entre dans la case voisine avec ce secteur, reduit par les portails deja
     * traverses ; si le secteur est vide, la case est invisible et on s'arrete. Aucun lancer de rayon :
     * deux produits vectoriels par portail. Une case cachee derriere un mur plein n'est jamais atteinte.
     * Une case atteinte par plusieurs chemins garde l'union de leurs secteurs (reste conservateur).
     */
    calcWallsVisibility() {
        const S = Raycaster.WALL_SIZE;
        const gx = this.mazeGridX, gy = this.mazeGridY;
        const walls = this._walls;
        const queue = this._queue;
        const stamp = this._cellStamp;   // === mark : case deja retenue (murs emis)
        const queued = this._cellQueued; // === mark : case actuellement dans la file
        const mark = ++this._cellFrame;

        // reperes de la camera pour le test de zone (voir _inView)
        const idx = this.player.angleIndex;
        this._vc = COS[idx];
        this._vs = SIN[idx];
        this._vh = 0.5 * (Math.abs(this._vc) + Math.abs(this._vs));
        this._vx = this.player.x / S;
        this._vy = this.player.y / S;

        let n = 0;
        let head = 0, tail = 0, kept = 0;
        const start = BT.clamp(this.playerGridY, 0, gy - 1) * gx + BT.clamp(this.playerGridX, 0, gx - 1);
        queue[tail++] = start;
        queued[start] = mark;
        this._full[start] = 1; // la case du joueur : tout l'horizon

        while (head < tail) {
            const ci = queue[head++];
            queued[ci] = 0;
            const xx = ci % gx, yy = (ci / gx) | 0;
            const open = Raycaster.OPEN[this.maze[ci]];
            const x0 = S * xx, y0 = S * yy, x1 = x0 + S, y1 = y0 + S;

            if (stamp[ci] !== mark) { // premiere visite : on emet les murs de la case (une seule fois)
                stamp[ci] = mark;
                // au dela de la profondeur, on traverse la case (elle laisse voir plus loin) sans dessiner ses murs
                if (ci !== start && !this._inView(xx, yy, 0)) { /* traversee seulement */ } else {
                this._cells[kept * 2] = xx;
                this._cells[kept * 2 + 1] = yy;
                kept++;
                // haut, droite, bas, gauche (sens horaire) : un mur existe quand le cote est ferme
                if (!(open & Raycaster.N)) { walls[n++] = x0; walls[n++] = y0; walls[n++] = x1; walls[n++] = y0; }
                if (!(open & Raycaster.E)) { walls[n++] = x1; walls[n++] = y0; walls[n++] = x1; walls[n++] = y1; }
                if (!(open & Raycaster.S)) { walls[n++] = x1; walls[n++] = y1; walls[n++] = x0; walls[n++] = y1; }
                if (!(open & Raycaster.W)) { walls[n++] = x0; walls[n++] = y1; walls[n++] = x0; walls[n++] = y0; }
                }
            }

            // voisins par les passages ouverts (la grille est coherente : si A est ouvert vers B, B l'est vers A)
            if ((open & Raycaster.N) && yy > 0) tail = this._cross(ci, ci - gx, xx, yy - 1, x0, y0, x1, y0, mark, tail);
            if ((open & Raycaster.E) && xx < gx - 1) tail = this._cross(ci, ci + 1, xx + 1, yy, x1, y0, x1, y1, mark, tail);
            if ((open & Raycaster.S) && yy < gy - 1) tail = this._cross(ci, ci + gx, xx, yy + 1, x0, y1, x1, y1, mark, tail);
            if ((open & Raycaster.W) && xx > 0) tail = this._cross(ci, ci - 1, xx - 1, yy, x0, y0, x0, y1, mark, tail);
        }

        this._cellCount = kept;
        this._wallCount = n >> 2;
    }

    /**
     * Traverse le portail (pPx1,pPy1)-(pPx2,pPy2) de la case pFrom vers la case voisine pTo.
     * Renvoie la nouvelle fin de file.
     */
    _cross(pFrom, pTo, pXX, pYY, pPx1, pPy1, pPx2, pPy2, pMark, pTail) {
        if (!this._inView(pXX, pYY, 2)) return pTail; // marge : une case hors profondeur peut encore laisser voir une case dans la zone
        const cx = this.player.x, cy = this.player.y;
        const ax = pPx1 - cx, ay = pPy1 - cy, bx = pPx2 - cx, by = pPy2 - cy;
        const c = ax * by - ay * bx; // > 0 : b est a gauche (sens trigo) de a
        const win = this._win;
        const f = pFrom * 4;
        const full = this._full[pFrom] === 1;

        // secteur du portail : de R vers L (sens trigo, moins de 180 degres)
        let rx, ry, lx, ly, portalFull = false;
        if (c > 1e-9) { rx = ax; ry = ay; lx = bx; ly = by; }
        else if (c < -1e-9) { rx = bx; ry = by; lx = ax; ly = ay; }
        else { portalFull = true; rx = ry = lx = ly = 0; } // camera dans le plan du portail : demi-plan, on reste conservateur

        let nFull = false;
        if (portalFull) {
            if (!full) { rx = win[f]; ry = win[f + 1]; lx = win[f + 2]; ly = win[f + 3]; }
            else nFull = true;
        } else if (!full) {
            // intersection avec le secteur courant : R le plus "a gauche", L le plus "a droite"
            const sRx = win[f], sRy = win[f + 1], sLx = win[f + 2], sLy = win[f + 3];
            if (sRx * ry - sRy * rx < 0) { /* R du portail est a droite de R courant : on garde R courant */ rx = sRx; ry = sRy; }
            if (lx * sLy - ly * sLx < 0) { lx = sLx; ly = sLy; }
            // secteur vide ?
            if (rx * ly - ry * lx <= 1e-9) return pTail;
        }

        const t = pTo * 4;
        const mark = pMark;
        if (this._cellQueuedOrSeen(pTo, mark)) {
            // deja vue : on elargit son secteur si le nouveau n'est pas contenu dedans
            if (this._full[pTo] === 1) return pTail;
            if (nFull) { this._full[pTo] = 1; }
            else {
                let uRx = win[t], uRy = win[t + 1], uLx = win[t + 2], uLy = win[t + 3];
                let changed = false;
                if (uRx * ry - uRy * rx < -1e-9) { uRx = rx; uRy = ry; changed = true; } // le nouveau R est plus a droite (horaire)
                if (uLx * ly - uLy * lx > 1e-9) { uLx = lx; uLy = ly; changed = true; }  // le nouveau L est plus a gauche
                if (!changed) return pTail;
                // l'union depasse 180 degres : on passe en horizon complet
                if (uRx * uLy - uRy * uLx <= 0) this._full[pTo] = 1;
                else { win[t] = uRx; win[t + 1] = uRy; win[t + 2] = uLx; win[t + 3] = uLy; }
            }
        } else {
            this._full[pTo] = nFull ? 1 : 0;
            if (!nFull) { win[t] = rx; win[t + 1] = ry; win[t + 2] = lx; win[t + 3] = ly; }
        }
        if (this._cellQueued[pTo] !== mark) { // (re)mise en file
            this._cellQueued[pTo] = mark;
            if (pTail >= this._queue.length) return pTail; // (ne devrait pas arriver : garde-fou)
            this._queue[pTail++] = pTo;
        }
        return pTail;
    }

    _cellQueuedOrSeen(pCi, pMark) {
        return this._cellStamp[pCi] === pMark || this._cellQueued[pCi] === pMark;
    }

    /**
     * Brouillard : les traits s'eteignent progressivement avec la DISTANCE (reelle, pas la profondeur : le
     * resultat ne change pas quand le joueur tourne) : pleine couleur jusqu'a pStart cases, puis fondu vers
     * la couleur du fond, invisible a la limite de la zone de rendu. pStart = Infinity : pas de brouillard.
     * Les traits sont ranges par bande de distance (FOG_BANDS niveaux) : un seul appel de dessin par bande.
     */
    setFog(pStart = 1) {
        this.fogStart = pStart;
        this._applyFog();
        this._dirty = true;
    }

    _applyFog() {
        const NB = Raycaster.FOG_BANDS;
        const S = Raycaster.WALL_SIZE;
        if (this.fogStart === undefined) this.fogStart = Raycaster.DEFAULT_FOG_START;
        const end = this.viewDistance + 0.5; // meme limite que _inView
        this._fogOn = Number.isFinite(this.fogStart) && this.fogStart < end;
        this._fogStartPx = this._fogOn ? this.fogStart * S : 0;
        this._fogK = this._fogOn ? (NB - 1) / ((end - this.fogStart) * S) : 0;
        this._bandColor = new Array(NB);
        const bg = Config.color.DARKGRAY, fg = 0xFFD690;
        for (let b = 0; b < NB; b++) {
            const i = this._fogOn ? 1 - b / (NB - 1) : 1; // intensite : 1 (pres) .. 0 (limite)
            const r = ((bg >> 16) & 255) + (((fg >> 16) & 255) - ((bg >> 16) & 255)) * i;
            const g = ((bg >> 8) & 255) + (((fg >> 8) & 255) - ((bg >> 8) & 255)) * i;
            const bl = (bg & 255) + ((fg & 255) - (bg & 255)) * i;
            this._bandColor[b] = ((r + 0.5) << 16) | ((g + 0.5) << 8) | ((bl + 0.5) | 0);
        }
    }

    /** trace les traits accumules, bandes lointaines d'abord (la derniere bande = invisible, ignoree) */
    _flushBands() {
        const NB = Raycaster.FOG_BANDS;
        const bandN = this._bandN;
        for (let b = NB - 1; b >= 0; b--) {
            const n = bandN[b];
            if (n === 0) continue;
            if (b < NB - 1 || !this._fogOn) {
                this.strokeSegments(this._bandLines[b], n, 3, this._bandColor[b]);
                this._lineCountAcc += n >> 2;
            }
            bandN[b] = 0;
        }
    }

    /**
     * La case (xx, yy) est-elle (au moins en partie) dans la zone de rendu ? Repere camera : fz = devant,
     * ls = lateral (en cases). Une case est un carre : sa demi-etendue dans les axes de la camera est h.
     */
    _inView(pXX, pYY, pExtra = 0) {
        const dx = pXX + 0.5 - this._vx, dy = pYY + 0.5 - this._vy;
        const fz = dx * this._vc + dy * this._vs;
        const ls = Math.abs(dx * this._vs - dy * this._vc);
        const h = this._vh;
        if (fz + h < 0) return false;                                // derriere
        // trop loin : DISTANCE reelle au centre de la case (et non la profondeur fz : un plan de coupe fixe
        // laissait entrer des cases pendant une rotation, la profondeur d'une case changeant avec le cap)
        const lim = this.viewDistance + 0.5 + pExtra;
        if (dx * dx + dy * dy > lim * lim) return false;
        if (ls > fz + 2 * h) return false;                           // hors du champ de vision (|x| <= z a 90 degres)
        return ls - h <= this.viewSide;                              // limite laterale facultative
    }

    update(pDt) {
        this.time += pDt;
        // On ne redessine que si la vue a change (position, angle, ou mini-map affichee/masquee).
        if (this._dirty
            || this.lastPlayerX != this.player.x
            || this.lastPlayerY != this.player.y
            || this.lastPlayerAngle != this.player.angleIndex) {

            this._dirty = false;
            this.lastPlayerX = this.player.x; // oubli d'origine : sans cette ligne la condition etait toujours vraie
            this.lastPlayerY = this.player.y;
            this.lastPlayerAngle = this.player.angleIndex;

            this.updatePlayerGridPosition();
            this.calcWallsVisibility();

            // clear & init  the screen
            this.clear();
            this.lineStyle(3, Config.color.BEIGE);
            this.beginFill(Config.color.DARKGRAY);
            this.drawRect(0, 0, this.WIDTH, this.HEIGHT);
            this.endFill();
            
            // cameraCenter
            const CCX = 384;
            const CCY = 384;
            const CCR = 7168;// [4096..8192] ~ratio

            let ppx = this.player.x;
            let ppy = this.player.y;

            // Draw the transformed map, relative to the player
            const walls = this._walls;
            // cos/sin de l'angle : lus dans la table (plus aucun Math.cos/sin dans la boucle de dessin)
            const cosA = COS[this.player.angleIndex];
            const sinA = SIN[this.player.angleIndex];

            // Les lignes des murs sont accumulees dans un tampon puis tracees d'un seul coup
            // (une commande de dessin au lieu de 4 par mur).
            const bandN = this._bandN, bandL = this._bandLines;
            const NBM = Raycaster.FOG_BANDS - 1;
            const fogOn = this._fogOn, fogS = this._fogStartPx, fogK = this._fogK;
            this._lineCountAcc = 0;
            // bande de brouillard d'un point (repere camera) selon sa distance au joueur
            const band = (tx, tz) => {
                if (!fogOn) return 0;
                const b = ((Math.sqrt(tx * tx + tz * tz) - fogS) * fogK + 0.5) | 0;
                return b < 0 ? 0 : (b > NBM ? NBM : b);
            };
            const addLine = (b, xa, ya, xb, yb) => {
                const arr = bandL[b];
                let n = bandN[b];
                arr[n++] = xa; arr[n++] = ya; arr[n++] = xb; arr[n++] = yb;
                bandN[b] = n;
            };
            const frame = ++this._frame;

            // Mini-map de debug (espace) : cases RETENUES par la zone de rendu, en bleu pale
            if (this._spaceKeyCounter > 0) {
                this.lineStyle(0);
                this.beginFill(Config.color.LIGHTBLUE, 0.15);
                for (let i = 0; i < this._cellCount; i++) {
                    this.drawRect(this._cells[i * 2] * 32, this._cells[i * 2 + 1] * 32, 32, 32);
                }
                this.endFill();
            }

            // 2e mini-map (espace x2) : meme chose dans le repere du joueur (haut = devant), echelle 1:1
            if (this._spaceKeyCounter > 1) {
                this.lineStyle(0);
                this.beginFill(Config.color.LIGHTBLUE, 0.15);
                const CS = Raycaster.WALL_SIZE;
                for (let i = 0; i < this._cellCount; i++) {
                    const X0 = this._cells[i * 2] * CS, Y0 = this._cells[i * 2 + 1] * CS;
                    this.drawPolygon([
                        this._relX(X0, Y0), this._relY(X0, Y0), this._relX(X0 + CS, Y0), this._relY(X0 + CS, Y0),
                        this._relX(X0 + CS, Y0 + CS), this._relY(X0 + CS, Y0 + CS), this._relX(X0, Y0 + CS), this._relY(X0, Y0 + CS)]);
                }
                this.endFill();
            }
            const S = Raycaster.WALL_SIZE;
            const stride = this.mazeGridX + 1;
            for (let w = 0; w < this._wallCount; w++) {
                let ax = walls[w * 4], ay = walls[w * 4 + 1], bx = walls[w * 4 + 2], by = walls[w * 4 + 3];
                let c1 = false;
                let c2 = false;

                let tx1 = ax - ppx;
                let tx2 = bx - ppx;
                let ty1 = ay - ppy;
                let ty2 = by - ppy;

                //////////////////////////////////////////////////////////
                // Absolute map
                let px = ax;
                let py = ay;
                if (this._spaceKeyCounter > 0) {
                    // mur candidat (dans la zone de rendu) : gris, il passera en bleu s'il est visible
                    this.lineStyle(1, 0x8A8F99);
                    this.moveTo(px >> 1, py >> 1);
                    px = bx >> 1;
                    py = by >> 1;
                    this.lineTo(px, py);
                }
                if (this._spaceKeyCounter > 1) { // meme mur candidat dans le repere du joueur
                    this.lineStyle(1, 0x8A8F99);
                    this.moveTo(this._relX(ax, ay), this._relY(ax, ay));
                    this.lineTo(this._relX(bx, by), this._relY(bx, by));
                }

                // Visibilite DEPUIS LA CAMERA (la position du joueur, la meme que celle de la projection).
                // Le mur est coupe a la partie reellement visible : un mur entrevu par une ouverture n'est
                // ni supprime en bloc (il "pope" a l'ecran) ni dessine en entier derriere un autre mur.
                if (!this.visibleSpan(ax, ay, bx, by)) continue;
                const cutA = this._ta > 0;
                const cutB = this._tb < 1;
                if (cutA || cutB) {
                    const wx = bx - ax, wy = by - ay;
                    const nax = ax + wx * this._ta, nay = ay + wy * this._ta;
                    const nbx = ax + wx * this._tb, nby = ay + wy * this._tb;
                    ax = nax; ay = nay; bx = nbx; by = nby;
                    tx1 = ax - ppx; tx2 = bx - ppx; ty1 = ay - ppy; ty2 = by - ppy;
                }

                if (this._spaceKeyCounter > 0) { // partie reellement visible du mur
                    this.lineStyle(2, Config.color.LIGHTBLUE);
                    this.moveTo(ax / 2, ay / 2);
                    this.lineTo(bx / 2, by / 2);
                }

                // rays to corner
                if (this._spaceKeyCounter > 0) this.lineStyle(1, Config.color.ORANGE);
                let dx = ax - this.player.x;
                let dy = ay - this.player.y;
                const vpx = cosA;
                const vpy = sinA;
                if (dx * vpx + dy * vpy >= 0) {
                    if (this._spaceKeyCounter > 0) {
                        this.moveTo(this.player.x >> 1, this.player.y >> 1);
                        this.lineTo(ax >> 1, ay >> 1);
                    }
                } else {
                    c1 = true;
                }
                dx = bx - this.player.x;
                dy = by - this.player.y;
                if (dx * vpx + dy * vpy >= 0) {
                    if (this._spaceKeyCounter > 0) {
                        this.moveTo(this.player.x >> 1, this.player.y >> 1);
                        this.lineTo(bx >> 1, by >> 1);
                    }
                } else {
                    c2 = true;
                }

                // pas besoin d'aller plus loin lorsque les 2 vertex d'un mur sont derrière le joueur
                if (c1 && c2) {
                    continue;
                }
                let tz1 = tx1 * cosA + ty1 * sinA;
                let tz2 = tx2 * cosA + ty2 * sinA;
                tx1 = tx1 * sinA - ty1 * cosA;
                tx2 = tx2 * sinA - ty2 * cosA;

                if (this._spaceKeyCounter > 1) {
                    this.lineStyle(2, Config.color.LIGHTBLUE);
                    this.moveTo(576 - tx1, 520 - tz1);
                    this.lineTo(576 - tx2, 520 - tz2);
                }

                //////////////////////////////////////////////////////////
                // Transformed map
                if (tz1 > 0 || tz2 > 0) {
                    // un sommet dont tz > 0 n'est pas modifie : sa projection ne depend que de lui
                    const v1ok = tz1 > 0;
                    const v2ok = tz2 > 0;

                    // le mur traverse le plan du joueur : on le coupe (calcul seulement dans ce cas)
                    if (!v1ok || !v2ok) {
                        this.intersect(tx1, tz1, tx2, tz2, -0.0001, 0.0001, -CCX, 5);
                        const p1x = this._ix, p1z = this._iz;
                        this.intersect(tx1, tz1, tx2, tz2, 0.0001, 0.0001, CCX, 5);
                        const p2x = this._ix, p2z = this._iz;
                        if (!v1ok) {
                            if (p1z > 0) { tx1 = p1x; tz1 = p1z; } else { tx1 = p2x; tz1 = p2z; }
                        }
                        if (!v2ok) {
                            if (p1z > 0) { tx2 = p1x; tz2 = p1z; } else { tx2 = p2x; tz2 = p2z; }
                        }
                    }

                    const x1 = -tx1 * CCX / tz1;
                    const x2 = -tx2 * CCX / tz2;
                    const y1a = -CCR / tz1;
                    const y2a = -CCR / tz2;
                    const y1b = CCR / tz1;
                    const y2b = CCR / tz2;

                    if (x1 <= x2) {
                        // haut et bas, par morceaux d'environ 16 unites : chaque morceau a la couleur de sa distance
                        // (la profondeur est lineaire le long d'un mur : on interpole dans le repere camera)
                        const dtx = tx2 - tx1, dtz = tz2 - tz1;
                        const np = fogOn ? Math.min(4, Math.ceil(Math.sqrt(dtx * dtx + dtz * dtz) / 16)) : 1;
                        let xa = x1, za = tz1;
                        for (let q = 1; q <= np; q++) {
                            const u = q / np;
                            const txb = q === np ? tx2 : tx1 + dtx * u;
                            const zb = q === np ? tz2 : tz1 + dtz * u;
                            const xb = q === np ? x2 : -txb * CCX / zb;
                            const um = (q - 0.5) / np;
                            const b = band(tx1 + dtx * um, tz1 + dtz * um);
                            addLine(b, CCX + xa, CCY - CCR / za, CCX + xb, CCY - CCR / zb);
                            addLine(b, CCX + xa, CCY + CCR / za, CCX + xb, CCY + CCR / zb);
                            xa = xb; za = zb;
                        }
                        // les aretes verticales : deux murs qui se touchent partagent la meme arete, on ne la trace qu'une fois
                        // (seulement si le sommet n'a pas ete coupe, sinon sa position depend du mur)
                        // (sommets coupes par la visibilite : pas sur la grille, jamais partages -> toujours traces)
                        const k1 = cutA ? 0 : (ay / S) * stride + ax / S;
                        const k2 = cutB ? 0 : (by / S) * stride + bx / S;
                        if (cutA || !v1ok || this._vStamp[k1] !== frame) {
                            if (v1ok && !cutA) this._vStamp[k1] = frame;
                            addLine(band(tx1, tz1), CCX + x1, CCY + y1a, CCX + x1, CCY + y1b);
                        }
                        if (cutB || !v2ok || this._vStamp[k2] !== frame) {
                            if (v2ok && !cutB) this._vStamp[k2] = frame;
                            addLine(band(tx2, tz2), CCX + x2, CCY + y2a, CCX + x2, CCY + y2b);
                        }
                        // mini-map affichee : on trace mur par mur pour garder l'ordre de superposition des traits
                        if (this._spaceKeyCounter > 0) this._flushBands();
                    }
                }
            }
            this._flushBands();
            this.lastLineCount = this._lineCountAcc; // statistique : traits dessines cette image (utile pour juger d'un portage)

            // ennemis (sprites poses sur le sol, taille selon la distance)
            this._updateEnemies(CCX, CCY, CCR, ppx, ppy, cosA, sinA);

            ////////////////////////////////////////////////////
            // mini maps
            // draw the player for absolute map
            if (this._spaceKeyCounter > 0) {
                this.lineStyle(1, Config.color.ORANGE);
                this.beginFill(Config.color.BLACK);
                this.drawCircle(this.player.x >> 1, this.player.y >> 1, 2.5);
                this.moveTo(this.player.x >> 1, this.player.y >> 1);
                this.lineStyle(2, Config.color.BLACK);
                let fw = this.player.forward(10);
                this.lineTo(fw.x >> 1, fw.y >> 1);

                // ennemis (points rouges)
                this.lineStyle(1, Config.color.WHITE);
                this.beginFill(Config.color.RED);
                for (const e of DatasManager.enemies) {
                    this.drawCircle(e.x >> 1, e.y >> 1, 2.5);
                }
            }

            // draw the player for relative  map (meme style que sur la mini-map absolue)
            if (this._spaceKeyCounter > 1) {
                this.lineStyle(1, Config.color.ORANGE);
                this.beginFill(Config.color.BLACK);
                this.drawCircle(576, 520, 2.5);
                this.moveTo(576, 520);
                this.lineStyle(2, Config.color.BLACK);
                this.lineTo(576, 510);
            }
        }
    }

    /**
     * Projection des ennemis, avec les MEMES formules que les murs : pour un point du labyrinthe a la
     * profondeur tz (devant le joueur) et au decalage lateral tx,
     *   ecran x = CCX - tx * CCX / tz        (centre du couloir)
     *   sol    y = CCY + CCR / tz            (le bas des murs : la ou le couloir touche le sol)
     * Le sprite a ses pieds en (x, sol) et mesure Raycaster.ENEMY_HEIGHT unites du monde : sa hauteur a
     * l'ecran est donc ENEMY_HEIGHT * CCX / tz, exactement l'echelle des murs. Cache s'il est derriere
     * le joueur, hors de la zone de rendu ou masque par un mur (rayon camera -> centre de la case).
     */
    _updateEnemies(CCX, CCY, CCR, ppx, ppy, cosA, sinA) {
        const enemies = DatasManager.enemies;
        for (let i = 0; i < enemies.length; i++) {
            const e = enemies[i], spr = this._enemySprites[i];
            const ex = e.x, ey = e.y; // position en pixels du labyrinthe (l'ennemi se deplace)
            const rx = ex - ppx, ry = ey - ppy;
            const tz = rx * cosA + ry * sinA;
            const tx = rx * sinA - ry * cosA;
            const sx = CCX - tx * CCX / tz;
            spr.visible = tz > Raycaster.ENEMY_NEAR
                && Math.abs(sx - CCX) < CCX + spr.width
                && this._inView(e.gridX, e.gridY, 0)
                && this._enemySeen(ppx, ppy, ex, ey, rx, ry);
            if (!spr.visible) continue;
            spr.x = sx;
            spr.y = CCY + CCR / tz;
            spr.scale.set(Raycaster.ENEMY_HEIGHT * CCX / tz / spr.texture.height);
            spr.zIndex = -tz;
            // brouillard : le sprite s'estompe comme les murs (meme distance, meme intensite)
            if (this._fogOn) {
                const a = 1 - (Math.sqrt(tx * tx + tz * tz) - this._fogStartPx) * this._fogK / (Raycaster.FOG_BANDS - 1);
                spr.alpha = a < 0 ? 0 : (a > 1 ? 1 : a);
            } else spr.alpha = 1;
        }
    }

    /**
     * L'ennemi est-il vu EN ENTIER ? Rayons camera -> centre ET camera -> les deux flancs (+-8 unites,
     * perpendiculairement a la ligne de visee, ~ la demi-largeur du sprite) : les trois doivent etre libres.
     * Un sprite est une image plate : on ne peut pas n'en montrer que la partie visible, alors on le cache
     * des qu'un mur en masque un bord (typiquement : monstre derriere l'angle d'un couloir). Un rayon qui
     * frole exactement un coin de la grille ne bloque pas, c'est une raison de plus de tester les flancs.
     */
    _enemySeen(ppx, ppy, ex, ey, rx, ry) {
        if (this.rayBlocked(ppx, ppy, ex, ey)) return false;
        const len = Math.hypot(rx, ry) || 1;
        const ox = -ry / len * 8, oy = rx / len * 8;
        return !this.rayBlocked(ppx, ppy, ex + ox, ey + oy) && !this.rayBlocked(ppx, ppy, ex - ox, ey - oy);
    }

    // debug : coordonnees ecran (mini-map relative centree en 576,520, haut = devant) d'un point du labyrinthe
    _relX(pX, pY) {
        const idx = this.player.angleIndex;
        return 576 - ((pX - this.player.x) * SIN[idx] - (pY - this.player.y) * COS[idx]);
    }
    _relY(pX, pY) {
        const idx = this.player.angleIndex;
        return 520 - ((pX - this.player.x) * COS[idx] + (pY - this.player.y) * SIN[idx]);
    }

    // --------------------------------------------------
    // Labyrinthe pour les ennemis

    /** la case (gx, gy) a-t-elle un passage ouvert dans la direction absolue pDir (0=E 1=S 2=O 3=N) ? */
    isOpen(gx, gy, pDir) {
        if (gx < 0 || gy < 0 || gx >= this.mazeGridX || gy >= this.mazeGridY) return false;
        return (Raycaster.OPEN[this.maze[gy * this.mazeGridX + gx]] & Raycaster.DIR_FLAG[pDir]) !== 0;
    }

    /**
     * Distances (en cases, par les couloirs ouverts) depuis la case du joueur : parcours en largeur, recalcule
     * seulement quand le joueur change de case. Ensuite pathDistance(gx, gy) lit le resultat (-1 : inaccessible).
     */
    pathDistance(gx, gy) {
        const W = this.mazeGridX;
        const pgx = (this.player.x / Raycaster.WALL_SIZE) | 0, pgy = (this.player.y / Raycaster.WALL_SIZE) | 0;
        if (!this._dist) {
            this._dist = new Int16Array(W * this.mazeGridY);
            this._distQueue = new Int16Array(W * this.mazeGridY);
            this._distKey = -1;
        }
        const key = pgy * W + pgx;
        if (this._distKey !== key) {
            this._distKey = key;
            const dist = this._dist, q = this._distQueue;
            dist.fill(-1);
            let head = 0, tail = 0;
            dist[key] = 0;
            q[tail++] = key;
            while (head < tail) {
                const c = q[head++], cx = c % W, cy = (c / W) | 0;
                for (let d = 0; d < 4; d++) {
                    if (!this.isOpen(cx, cy, d)) continue;
                    const n = (cy + Raycaster.DIR_DY[d]) * W + cx + Raycaster.DIR_DX[d];
                    if (dist[n] < 0) { dist[n] = dist[c] + 1; q[tail++] = n; }
                }
            }
        }
        if (gx < 0 || gy < 0 || gx >= W || gy >= this.mazeGridY) return -1;
        return this._dist[gy * W + gx];
    }

    /** demande un redessin a la prochaine image (ex. : un ennemi visible a bouge) */
    invalidate() { this._dirty = true; }

    // Gameplay
    hitSpace() {
        this._spaceKeyCounter = this._spaceKeyCounter + 1;
        if (this._spaceKeyCounter > 2) {
            this._spaceKeyCounter = 0;
        }
        this._dirty = true; // la mini-map change sans que le joueur bouge
    }

    // Maths tools
    /**
     * Partie visible d'un mur depuis la camera (position du joueur). Ecrit dans this._ta / this._tb
     * l'intervalle [ta, tb] (0..1 le long du mur) et renvoie false si rien n'est visible.
     * On teste le point a 0.5 px de chaque extremite (un rayon qui frole exactement un coin de la
     * grille est un cas degenere) ; si une seule extremite est visible, on cherche la limite par
     * dichotomie (6 coupes = 1 px sur un mur de 64).
     */
    visibleSpan(x1, y1, x2, y2) {
        const px = this.player.x, py = this.player.y;
        const wx = x2 - x1, wy = y2 - y1;
        // camera exactement dans le plan du mur (cas d'un joueur sur une ligne de la grille) : mur vu par la tranche, invisible
        if ((wx === 0 && px === x1) || (wy === 0 && py === y1)) return false;
        const len = Math.abs(wx) + Math.abs(wy); // murs alignes sur la grille
        const e = 0.5 / len;
        const seen = (t) => !this.rayBlocked(px, py, x1 + wx * t, y1 + wy * t);
        const v0 = seen(e), v1 = seen(1 - e);
        this._ta = 0; this._tb = 1;
        if (v0 && v1) return true;
        if (!v0 && !v1) {
            // les deux bouts masques : on regarde si le milieu est visible (deux fentes) sinon mur cache
            if (!seen(0.5)) return false;
            this._ta = this._limit(seen, 0.5, e);
            this._tb = this._limit(seen, 0.5, 1 - e);
            return true;
        }
        if (v0) this._tb = this._limit(seen, e, 1 - e);
        else this._ta = this._limit(seen, 1 - e, e);
        return true;
    }

    /** dichotomie : pTrue = point visible, pFalse = point masque ; renvoie la frontiere (cote visible) */
    _limit(pSeen, pTrue, pFalse) {
        let a = pTrue, b = pFalse;
        for (let i = 0; i < 6; i++) {
            const m = (a + b) * 0.5;
            if (pSeen(m)) a = m; else b = m;
        }
        return a;
    }

    /**
     * Tables des aretes de la grille : _edgeV[row * (gridX + 1) + col] est vrai s'il y a un mur sur
     * l'arete verticale x = col * 64 (entre les cellules col-1 et col de la ligne row), _edgeH[row * gridX + col]
     * pour l'arete horizontale y = row * 64. Une arete est un mur quand le cote de la cellule qui la
     * borde est ferme (meme resultat que les murs dessines par chaque cellule).
     */
    _buildEdges() {
        const gx = this.mazeGridX, gy = this.mazeGridY;
        this._edgeV = new Uint8Array((gx + 1) * gy);
        this._edgeH = new Uint8Array(gx * (gy + 1));
        for (let y = 0; y < gy; y++) {
            for (let x = 0; x < gx; x++) {
                const open = Raycaster.OPEN[this.maze[y * gx + x]];
                if (!(open & Raycaster.N)) this._edgeH[y * gx + x] = 1;
                if (!(open & Raycaster.S)) this._edgeH[(y + 1) * gx + x] = 1;
                if (!(open & Raycaster.W)) this._edgeV[y * (gx + 1) + x] = 1;
                if (!(open & Raycaster.E)) this._edgeV[y * (gx + 1) + x + 1] = 1;
            }
        }
    }

    /**
     * Le segment (x1,y1)->(x2,y2) traverse-t-il un mur ? On ne regarde que les lignes de la grille que le
     * segment franchit : pour chacune on calcule ou il la coupe et on lit dans la table s'il y a un mur
     * a cet endroit (~4 lectures au lieu de tester tous les murs un par un).
     * Un contact exact avec une extremite de mur (coin de la grille) ne bloque pas.
     */
    rayBlocked(x1, y1, x2, y2) {
        const S = Raycaster.WALL_SIZE;
        const gx = this.mazeGridX, gy = this.mazeGridY;
        const dx = x2 - x1, dy = y2 - y1;
        const EPS = 1e-9;

        // lignes verticales x = k * 64 strictement entre x1 et x2
        if (dx !== 0) {
            const kMin = Math.floor(Math.min(x1, x2) / S) + 1;
            const kMax = Math.ceil(Math.max(x1, x2) / S) - 1;
            for (let k = kMin; k <= kMax; k++) {
                const y = y1 + ((k * S - x1) / dx) * dy;
                const row = Math.floor(y / S);
                if (Math.abs(y - Math.round(y / S) * S) < EPS) continue; // passe par un coin
                if (row >= 0 && row < gy && k >= 0 && k <= gx && this._edgeV[row * (gx + 1) + k]) return true;
            }
        }
        // lignes horizontales y = k * 64
        if (dy !== 0) {
            const kMin = Math.floor(Math.min(y1, y2) / S) + 1;
            const kMax = Math.ceil(Math.max(y1, y2) / S) - 1;
            for (let k = kMin; k <= kMax; k++) {
                const x = x1 + ((k * S - y1) / dy) * dx;
                const col = Math.floor(x / S);
                if (Math.abs(x - Math.round(x / S) * S) < EPS) continue;
                if (col >= 0 && col < gx && k >= 0 && k <= gy && this._edgeH[k * gx + col]) return true;
            }
        }
        return false;
    }

    cross(x1, y1, x2, y2) {
        return x1 * y2 - y1 * x2;
    }

    /**
     * Intersection des droites (x1,y1)-(x2,y2) et (x3,y3)-(x4,y4) ; resultat dans this._ix / this._iz
     * (formule classique des deux determinants ; l'ancienne version reutilisait un x deja ecrase pour calculer y).
     */
    intersect(x1, y1, x2, y2, x3, y3, x4, y4) {
        const a = this.cross(x1, y1, x2, y2);
        const b = this.cross(x3, y3, x4, y4);
        const det = this.cross(x1 - x2, y1 - y2, x3 - x4, y3 - y4);
        this._ix = this.cross(a, x1 - x2, b, x3 - x4) / det;
        this._iz = this.cross(a, y1 - y2, b, y3 - y4) / det;
    }
}

Raycaster.WALL_SIZE = 64;
Raycaster.DEFAULT_VIEW_DISTANCE = 4; // profondeur en cases
Raycaster.DEFAULT_FOG_START = 1;     // le brouillard commence a cette distance (en cases)
Raycaster.FOG_BANDS = 12;            // niveaux d'intensite du brouillard
Raycaster.ENEMY_HEIGHT = 28;         // hauteur d'un ennemi, en unites du monde (un mur en mesure 2 * CCR / CCX = ~37)
Raycaster.ENEMY_NEAR = 12;           // un ennemi plus proche que ca (en unites) est cache

// Cotes ouverts d'une cellule (N=haut, E=droite, S=bas, W=gauche)
Raycaster.N = 1;
Raycaster.E = 2;
Raycaster.S = 4;
Raycaster.W = 8;
// directions absolues (0=E 1=S 2=O 3=N) : drapeau de passage et deplacement en cases
Raycaster.DIR_FLAG = [Raycaster.E, Raycaster.S, Raycaster.W, Raycaster.N];
Raycaster.DIR_DX = [1, 0, -1, 0];
Raycaster.DIR_DY = [0, 1, 0, -1];

// Code de cellule du labyrinthe (0x0..0xF) -> masque des passages ouverts.
// 0 = roche pleine, 1..4 = cul-de-sac (N, E, S, W), 5..8 = coudes, 9 et A = couloirs,
// B..E = 3 passages (un mur), F = carrefour.
Raycaster.OPEN = [
    0,
    Raycaster.N, Raycaster.E, Raycaster.S, Raycaster.W,
    Raycaster.N | Raycaster.W, Raycaster.N | Raycaster.E, Raycaster.S | Raycaster.W, Raycaster.E | Raycaster.S,
    Raycaster.E | Raycaster.W, Raycaster.N | Raycaster.S,
    Raycaster.E | Raycaster.S | Raycaster.W, Raycaster.N | Raycaster.S | Raycaster.W,
    Raycaster.N | Raycaster.E | Raycaster.W, Raycaster.N | Raycaster.E | Raycaster.S,
    Raycaster.N | Raycaster.E | Raycaster.S | Raycaster.W
];
