import { BT } from '../../../engine/BT.js';
import { GameInput } from '../../../engine/GameInput.js';
import { ControlableEntity } from '../../../engine/ControlableEntity.js';

// ---------------------------------------------------------------------------------------------
// Angle ENTIER : un tour complet = 80 crans de 4.5 degres (un quart de tour = 20 crans, soit
// 20 images de rotation comme avant). cos/sin sont lus dans des tables precalculees : plus de
// Math.cos/Math.sin, plus de flottant qui derive, et les 4 directions cardinales sont EXACTES
// (0 / 1 / -1, jamais 6e-17). C'est aussi ce qu'on ferait sur Gamebuino/Amiga (table en ROM).
// Repere ecran : x vers la droite, y vers le BAS. cran 0 = Est, 20 = Sud, 40 = Ouest, 60 = Nord.
// ---------------------------------------------------------------------------------------------
export const ANGLE_STEPS = 80;
export const ANGLE_QUARTER = ANGLE_STEPS / 4;
export const COS = new Float64Array(ANGLE_STEPS);
export const SIN = new Float64Array(ANGLE_STEPS);
for (let i = 0; i < ANGLE_STEPS; i++) {
    COS[i] = Math.cos(i * 2 * Math.PI / ANGLE_STEPS);
    SIN[i] = Math.sin(i * 2 * Math.PI / ANGLE_STEPS);
}
// valeurs exactes aux 4 points cardinaux
for (let q = 0; q < 4; q++) {
    const i = q * ANGLE_QUARTER;
    COS[i] = [1, 0, -1, 0][q];
    SIN[i] = [0, 1, 0, -1][q];
}

// facing : 0 = Est, 1 = Sud, 2 = Ouest, 3 = Nord (= angleIndex / 20 quand on est sur un quart)
const DIR_X = [1, 0, -1, 0];
const DIR_Y = [0, 1, 0, -1];

export class PlayerTopDown extends ControlableEntity {
    /** @param pInitialAngleIndex cran 0..79 (60 = Nord) */
    constructor(pGameInput, pTexture, pInitialX = 0, pInitialY = 0, pInitialAngleIndex = 60) {
        super(pGameInput, pTexture);
        this.anchor.x = this.anchor.y = .5;

        // -- Position
        this.x = pInitialX;
        this.y = pInitialY;

        this._vx = 0;
        this._vy = 0;

        // -- Orientation (entiers)
        this.angleIndex = ((pInitialAngleIndex % ANGLE_STEPS) + ANGLE_STEPS) % ANGLE_STEPS;
        this.facing = (this.angleIndex / ANGLE_QUARTER) | 0; // cap "logique" (pendant une rotation : le cap d'ARRIVEE)
        this._turn = 0;              // vitesse de rotation en crans/pas : -1, 0, +1

        // -- Movement
        this._WALK_SPEED = 2;

        // -- Keys
        this._UP = false;
        this._DW = false;
        this._LF = false;
        this._RG = false;
        this._RL = false;
        this._RR = false;

        // -- Walls : ouvert (true) / ferme, indexes N, E, S, W (absolus)
        this.walls = [true, true, true, true];

        // -- [*]
        this._moving = false;
    }

    /** cos/sin du cap actuel (lus dans les tables) */
    get cos() { return COS[this.angleIndex]; }
    get sin() { return SIN[this.angleIndex]; }

    /** direction absolue (0=E 1=S 2=O 3=N) visee par une touche, selon le cap : haut = devant, droite = +1... */
    _absDir(pRel) { return (this.facing + pRel) & 3; }

    /** vrai si la case voisine dans cette direction absolue est ouverte (walls est indexe N,E,S,W) */
    _open(pAbsDir) { return this.walls[(pAbsDir + 1) & 3]; }

    /** pRel : 0 = haut/devant, 1 = droite, 2 = bas/arriere, 3 = gauche */
    _canWalk(pRel) { return this._open(this._absDir(pRel)); }

    get _onQuarter() { return (this.angleIndex % ANGLE_QUARTER) == 0; }

    /** angle en radians (compat. / debug uniquement : le jeu n'utilise que angleIndex) */
    get angle() { return this.angleIndex * 2 * Math.PI / ANGLE_STEPS; }

    forward(pScale = 1.0){
        return { x: this.x + (this.cos * pScale), y: this.y + (this.sin * pScale) }
    }

    // Une touche de deplacement : on ne garde qu'UNE direction a la fois, et seulement si le mur le permet.
    _move(pRel) {
        this._UP = this._RG = this._DW = this._LF = false;
        const canWalk = this._canWalk(pRel);
        if (pRel === 0) this._UP = canWalk;
        else if (pRel === 1) this._RG = canWalk;
        else if (pRel === 2) this._DW = canWalk;
        else this._LF = canWalk;
    }

    /** remet les touches a zero (ex : changement de disposition clavier pendant qu'une touche est tenue,
     *  le relachement de l'ancienne touche n'arrive jamais) */
    clearInputs() {
        this._UP = this._DW = this._LF = this._RG = false;
        this._RL = this._RR = false;
    }

    upIsDown() { this._move(0); }
    upIsUp() { }
    upOnPress() { }
    upOnRelease() { this._UP = false; }

    downIsDown() { this._move(2); }
    downIsUp() { }
    downOnPress() { }
    downOnRelease() { this._DW = false; }

    leftIsDown() { this._move(3); }
    leftIsUp() { }
    leftOnPress() { }
    leftOnRelease() { this._LF = false; }

    rightIsDown() { this._move(1); }
    rightIsUp() { }
    rightOnPress() { }
    rightOnRelease() { this._RG = false; }

    action1IsDown() { }
    action1IsUp() { }
    action1OnPress() { }
    action1OnRelease() {
        BT.currentScreen.flash(0xFFFFFF); BT.currentScreen.playerAction(GameInput.ACTION1);
    }

    // Rotation : les touches ne font que lever un drapeau, update() fait tourner l'angle cran par cran.
    // On ne prend en compte une nouvelle demande de rotation que sur un quart exact : un quart de tour
    // commence est toujours termine (comme dans l'ancien code, qui bloquait les touches en cours de route).
    action2IsDown() { if (this._onQuarter && !this._RL) this._RR = true; } // droite = sens horaire a l'ecran (la 1re touche appuyee garde la main)
    action2IsUp() { }
    action2OnPress() { }
    action2OnRelease() { this._RR = false; }

    action3IsDown() { if (this._onQuarter && !this._RR) this._RL = true; } // gauche
    action3IsUp() { }
    action3OnPress() { }
    action3OnRelease() { this._RL = false; }

    /** UN pas de simulation (appeler a frequence fixe : 60 fois par seconde) */
    update() {
        const onCell = ((this.x + 32) % 64 == 0) && ((this.y + 32) % 64 == 0);
        const onQuarter = this._onQuarter;

        if (onCell) {
            this._vx = 0;
            this._vy = 0;
            if (!this._RR && !this._RL) {
                const s = this._WALK_SPEED;
                // on revalide chaque direction contre les murs de la case au moment de partir : un drapeau
                // reste leve tant que la touche n'a pas ete relachee, meme si plus aucun xxxIsDown() n'arrive
                if (this._UP && !this._canWalk(0)) this._UP = false;
                if (this._RG && !this._canWalk(1)) this._RG = false;
                if (this._DW && !this._canWalk(2)) this._DW = false;
                if (this._LF && !this._canWalk(3)) this._LF = false;
                if (this._UP) { const d = this._absDir(0); this._vx += DIR_X[d] * s; this._vy += DIR_Y[d] * s; }
                if (this._RG) { const d = this._absDir(1); this._vx += DIR_X[d] * s; this._vy += DIR_Y[d] * s; }
                if (this._DW) { const d = this._absDir(2); this._vx += DIR_X[d] * s; this._vy += DIR_Y[d] * s; }
                if (this._LF) { const d = this._absDir(3); this._vx += DIR_X[d] * s; this._vy += DIR_Y[d] * s; }
            }
        }

        if (onQuarter) {
            // on est sur un quart exact (arret, ou un quart de tour vient de finir) : on decide de la suite.
            // facing = cap ou l'on va (la rotation continue sur 20 crans meme si on relache la touche).
            this._turn = this._RR ? 1 : (this._RL ? -1 : 0);
            this.facing = ((this.angleIndex / ANGLE_QUARTER) + this._turn + 4) & 3;
        }

        this.x += this._vx;
        this.y += this._vy;
        this.angleIndex = (this.angleIndex + this._turn + ANGLE_STEPS) % ANGLE_STEPS;
    }
}
