import { gsap } from 'gsap';
import { Text } from '../../../core/fff.js';

export class BubblePoint extends Text {

    constructor(pStyle) {
        super("", pStyle);
        this.anchor.set(.5, .5);
        this.eventMode = 'none';
    }

    show(pValue, px, py) {
        this.text = pValue.toString();
        this.x = px;
        this.y = py;
        this.alpha = 1;

        // overwrite 'auto' : un nouveau show() remplace les tweens encore en cours (comportement de GSAP 1)
        gsap.to(this, { duration: 1 / 3, y: py - 40, ease: 'expo.out', overwrite: 'auto' });
        gsap.to(this, { duration: 1 / 3, alpha: 0, ease: 'expo.in', overwrite: 'auto' });

        return this;
    }
}