import { Sprite } from '../../../core/fff.js';

export class Monstre extends Sprite {
    constructor(ptexture, pGridX, pGridY, pXP) {
        super(ptexture);
        this.anchor.set(.5, 1);

        this.gridX = (pGridX * 64) + 32;
        this.gridY = (pGridY * 64) + 32;

        this._px = this.px = .5;
        this._py = this.py = .5;

        this.angle = Math.PI / 2;

        this.scale.set(6);

        this._xp = pXP;
    }

    // experience
    get xp() {
        return this._xp;
    }

    get px() {
        return this._px;
    }
    set px(pValue) {
        this._px = pValue;
        this.x = pValue * 768;
    }

    get py() {
        return this._py;
    }
    set py(pValue) {
        this._py = pValue;
    }

    forward(pScale = 1.0) {
        return { x: this.gridX + (Math.cos(this.angle) * pScale), y: this.gridY + (Math.sin(this.angle) * pScale) }
    }
}