// l'invoker stocke les commande dans l'ordre, via sore command
// garde en mémoire un curseur pour se deplacer dans la liste
// il utilise la ref fournie par le receiver pour lui dire qu'il est temps d'appliquer le resultat de cette commande
// charge au receiver d'appliquer le resultat à sa facon (voir AttaqueReceiver)
// on peut tout a fait imaginer remplacer le tableau command par une Priority queue ce qui permettrait d'ordonner les commandes par priorité
export class Invoker {
    constructor() {
        this._commands = [];
        this._cursor = 0;
    }

    storeCommand(pCommand) {
        this._commands.push(pCommand);
    }

    execute() {
        if (this._cursor < this._commands.length) {
            let currentCommand = this._commands[this._cursor];
            let result = currentCommand.execute();
            let receiver = currentCommand.receiver;
            receiver.applyCommandResult(result);
            this._cursor += 1;

            return true
        }

        return false;
    }

    executeAll() {
        let hasNext = true;
        while (hasNext) {
            hasNext = this.execute();
        }
    }

    undo() {
        if (this._cursor > 0) {
            this._cursor -= 1;
            let currentCommand = this._commands[this._cursor];
            let result = currentCommand.undo();
            let receiver = currentCommand.receiver;
            receiver.applyCommandResult(result);

            return true;
        }
        return false;
    }

    undoAll() {
        let hasNext = true;
        while (hasNext) {
            hasNext = this.undo();
        }
    }

}
