import { StateMachine } from '../../../engine/StateMachine.js';
import { Raycaster } from './Raycaster.js';

// = Raycaster.WALL_SIZE, recopie ici : Raycaster -> DatasManager -> Enemy -> Raycaster est un cycle d'imports,
// Raycaster ne doit donc etre lu qu'a l'execution (dans les methodes), jamais au chargement du module
const S = 64;

/**
 * Ennemi du labyrinthe (donnees + comportement, sans Pixi : le Raycaster dessine son sprite).
 * Position x, y en pixels du labyrinthe (centre de case = 64 * n + 32), qui survit aux changements d'ecran
 * (DatasManager.enemies). Il se deplace de case en case dans les couloirs ouverts.
 *
 *   PATROL  : avance au hasard (graine du jeu), sans faire demi-tour sauf en cul-de-sac
 *   CHASE   : le joueur est a moins de CHASE_RANGE cases PAR LES COULOIRS : il fonce vers lui, plus vite
 *   ENGAGED : combat declenche, il ne bouge plus (retire du labyrinthe au retour du combat)
 */
export class Enemy {
    constructor(pName, pGridX, pGridY) {
        this.name = pName;
        this.x = pGridX * S + S / 2;
        this.y = pGridY * S + S / 2;
        this.engaged = false;
        this.dir = -1;                 // direction du deplacement en cours : 0=E 1=S 2=O 3=N (-1 : aucune)
        this._tx = this.x;             // centre de la case visee
        this._ty = this.y;
        this._ctx = null;              // { raycaster, rng } fourni a chaque update()
        this.moved = false;            // a bouge pendant le dernier update() (le Raycaster doit redessiner)

        this.fsm = new StateMachine(this, {
            PATROL: {
                update: (e, dt) => e._walk(dt, Enemy.PATROL_SPEED, false),
                transitions: [{ to: 'CHASE', when: (e) => e._playerDistance() <= Enemy.CHASE_RANGE }]
            },
            CHASE: {
                update: (e, dt) => e._walk(dt, Enemy.CHASE_SPEED, true),
                transitions: [{ to: 'PATROL', when: (e) => e._playerDistance() > Enemy.LOSE_RANGE }]
            },
            ENGAGED: {
                enter: (e) => { e.engaged = true; }
            }
        }, 'PATROL');
    }

    get gridX() { return Math.floor(this.x / S); }
    get gridY() { return Math.floor(this.y / S); }

    /** combat declenche : l'ennemi s'arrete */
    engage() { this.fsm.change('ENGAGED'); }

    /** pCtx : { raycaster, rng } */
    update(pDt, pCtx) {
        this._ctx = pCtx;
        const x = this.x, y = this.y;
        this.fsm.update(pDt);
        this.moved = this.x !== x || this.y !== y;
    }

    /** distance (en cases, par les couloirs) jusqu'au joueur ; Infinity si inaccessible */
    _playerDistance() {
        const d = this._ctx.raycaster.pathDistance(this.gridX, this.gridY);
        return d < 0 ? Infinity : d;
    }

    // avance vers le centre de la case visee ; a l'arrivee, choisit la suivante
    _walk(pDt, pSpeed, pChase) {
        let budget = pSpeed * pDt;
        while (budget > 0) {
            if (this.dir < 0 || (this.x === this._tx && this.y === this._ty)) {
                if (!this._chooseNext(pChase)) return;
            }
            const dx = this._tx - this.x, dy = this._ty - this.y;
            const dist = Math.abs(dx) + Math.abs(dy); // deplacements alignes sur la grille
            if (dist <= budget) {
                this.x = this._tx; this.y = this._ty;
                budget -= dist;
            } else {
                this.x += Math.sign(dx) * budget;
                this.y += Math.sign(dy) * budget;
                budget = 0;
            }
        }
    }

    // choisit la direction de la prochaine case ; false si aucune (case isolee)
    _chooseNext(pChase) {
        const rc = this._ctx.raycaster, gx = this.gridX, gy = this.gridY;
        let dir = -1;
        if (pChase) {
            // descente de gradient sur les distances (par les couloirs) depuis le joueur
            let best = rc.pathDistance(gx, gy);
            for (let d = 0; d < 4; d++) {
                if (!rc.isOpen(gx, gy, d)) continue;
                const nd = rc.pathDistance(gx + Raycaster.DIR_DX[d], gy + Raycaster.DIR_DY[d]);
                if (nd >= 0 && nd < best) { best = nd; dir = d; }
            }
        }
        if (dir < 0) {
            // patrouille : une direction ouverte au hasard, sans faire demi-tour si on peut l'eviter
            const reverse = this.dir < 0 ? -1 : (this.dir + 2) & 3;
            const open = [];
            for (let d = 0; d < 4; d++) if (rc.isOpen(gx, gy, d) && d !== reverse) open.push(d);
            if (open.length === 0 && reverse >= 0 && rc.isOpen(gx, gy, reverse)) open.push(reverse);
            if (open.length === 0) { this.dir = -1; return false; }
            dir = this._ctx.rng.pick(open);
        }
        this.dir = dir;
        this._tx = (gx + Raycaster.DIR_DX[dir]) * S + S / 2;
        this._ty = (gy + Raycaster.DIR_DY[dir]) * S + S / 2;
        return true;
    }
}

Enemy.PATROL_SPEED = 24;  // px/s (le joueur marche a 120)
Enemy.CHASE_SPEED = 48;
Enemy.CHASE_RANGE = 4;    // cases, par les couloirs
Enemy.LOSE_RANGE = 7;
